pd-precreate.body:
Op 'mkdir Purge' { New-Item -ItemType Directory -Path 'C:\ProgramData\Purge' -ErrorAction Stop }
Op 'mkdir sessions' { New-Item -ItemType Directory -Path 'C:\ProgramData\Purge\sessions' -ErrorAction Stop }
Op 'mkdir Quarantine' { New-Item -ItemType Directory -Path 'C:\ProgramData\Purge\Quarantine' -ErrorAction Stop }
Op 'marker' { Set-Content -LiteralPath 'C:\ProgramData\Purge\purge-trap-precreated.txt' -Value 'created by a standard user (m2-traps pd-precreated)' -ErrorAction Stop }
Op 'junction Quarantine\planted' { MkJunction 'C:\ProgramData\Purge\Quarantine\planted' 'C:\PurgeCanary\pd\quarantine-target' }
Op 'junction sessions\planted' { MkJunction 'C:\ProgramData\Purge\sessions\planted' 'C:\PurgeCanary\pd\sessions-target' }

pd-plant.body:
Op 'create Quarantine\user-file.txt' { Set-Content -LiteralPath 'C:\ProgramData\Purge\Quarantine\user-file.txt' -Value x -ErrorAction Stop }
Op 'junction Quarantine\planted-post' { MkJunction 'C:\ProgramData\Purge\Quarantine\planted-post' 'C:\PurgeCanary\pd-post\target' }
Op 'create sessions\user-file.txt' { Set-Content -LiteralPath 'C:\ProgramData\Purge\sessions\user-file.txt' -Value x -ErrorAction Stop }
Op 'junction sessions\planted-post' { MkJunction 'C:\ProgramData\Purge\sessions\planted-post' 'C:\PurgeCanary\pd-post\target' }
Op 'create Purge\user-file.txt' { Set-Content -LiteralPath 'C:\ProgramData\Purge\user-file.txt' -Value x -ErrorAction Stop }
Op 'list Quarantine' { Get-ChildItem -LiteralPath 'C:\ProgramData\Purge\Quarantine' -Force -ErrorAction Stop }
Op 'read sessions\index.json' { Get-Content -LiteralPath 'C:\ProgramData\Purge\sessions\index.json' -ErrorAction Stop }
